\begin{lemma}\label{phisum}
If $G$ is an acyclic mixed graph, then $\chi_G(k) = \displaystyle\sum_{i=1}^m \phi_{G_i}(k) \, .$
\end{lemma}

\begin{theorem}[Stanley \cite{stanleythesis}]\label{stanley_op}
$  \Omega _{P,\omega} (-k) = (-1)^{|P|} \, \Omega_{P,\overline{\omega}} (k) \, .$
\end{theorem}

